select model_id from ry_business.ry_rental_stock_pool_compatibility
where tenant_id = #{tenantId} and member_id = #{memberId}
  and pool_id = #{poolId} and is_delete = 0 order by model_id

select count(1) from ry_business.ry_rental_asset_sn
where tenant_id = #{tenantId} and member_id = #{memberId}
  and sn_code = #{snCode} and is_delete = 0
  and sn_id != #{snId}

mapper.update:
update ry_business.ry_rental_asset_sn
set warehouse_id = #{warehouseId}, sn_code = #{snCode}, barcode = #{barcode}, asset_status = #{assetStatus},
    condition_level = #{conditionLevel}, update_by = #{operator}, update_time = now(), remark = #{remark}
where tenant_id = #{tenantId} and member_id = #{memberId}
  and sn_id = #{snId} and is_delete = 0

update ry_business.ry_rental_accessory_item
set warehouse_id = #{warehouseId}, item_code = #{itemCode}, item_status = #{itemStatus},
    update_by = #{operator}, update_time = now(), remark = #{remark}
where tenant_id = #{tenantId} and member_id = #{memberId}
  and accessory_item_id = #{accessoryItemId} and is_delete = 0

mapper.select:
select count(1) from ry_business.ry_rental_order_item
where tenant_id = #{tenantId} and member_id = #{memberId}
  and package_id = #{packageId} and is_delete = 0

select balance_id as id, on_hand_qty as onHandQty, version, stock_status as stockStatus
from ry_business.ry_rental_inventory_balance
where tenant_id = #{tenantId} and member_id = #{memberId}
  and product_id = #{productId} and warehouse_id = #{warehouseId}
  and stock_status = #{stockStatus} and is_delete = 0
for update

mapper.update:
update ry_business.ry_rental_inventory_balance
set on_hand_qty = #{quantity}, version = version + 1, update_by = #{operator}, update_time = now(), remark = #{remark}
where tenant_id = #{tenantId} and member_id = #{memberId}
  and balance_id = #{balanceId} and is_delete = 0

update ry_business.ry_rental_inventory_balance
set is_delete = 1, update_by = #{operator}, update_time = now()
where tenant_id = #{tenantId} and member_id = #{memberId}
  and product_id = #{productId} and warehouse_id = #{warehouseId}
  and stock_status = 'available' and on_hand_qty = 0 and is_delete = 0

