select coalesce(sum(required_qty), 0)
from ry_business.ry_rental_inventory_reservation_item
where tenant_id = #{tenantId} and member_id = #{memberId}
  and pool_id = #{poolId} and warehouse_id = #{warehouseId}
  and reservation_status = 'reserved' and is_delete = 0
